import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { Suspense } from "react";
import { SITE } from "@/lib/site";

// Starter policy text required for Razorpay website verification. The store owner should review these
// with their CA / legal adviser before going live.
const POLICIES: Record<string, { title: string; body: string[] }> = {
  shipping: {
    title: "Shipping & Delivery Policy",
    body: [
      `Orders are processed within 1–2 working days. Engraved and made-to-order items may take 3–5 working days before dispatch.`,
      `Delivery is free on orders above ₹999; a flat fee of ₹79 applies otherwise. Large appliances are delivered by our own team within Chengalpattu, Chennai, Kanchipuram and Puducherry districts; other locations are shipped via courier partners.`,
      `Typical delivery time is 2–7 working days depending on your PIN code. Tracking details are shared by SMS / WhatsApp once your order ships.`,
      `Installation for ACs, TVs and large appliances is coordinated with the brand's authorised service network or our technicians, as applicable.`,
    ],
  },
  returns: {
    title: "Returns, Replacement & Refund Policy",
    body: [
      `Items damaged in transit or with manufacturing defects can be reported within 7 days of delivery for a replacement or refund. Please share an unboxing photo/video on WhatsApp at ${SITE.phone}.`,
      `Personalised / engraved products cannot be returned unless defective. Appliances are covered by the manufacturer's warranty; we help you raise service requests.`,
      `Approved refunds are issued to the original payment method via Razorpay within 5–7 working days. For EMI purchases, the refund is credited to your card/lender and the EMI is cancelled or adjusted by your bank as per their policy.`,
      `Orders can be cancelled free of charge before dispatch.`,
    ],
  },
  privacy: {
    title: "Privacy Policy",
    body: [
      `${SITE.name} collects your name, contact details and delivery address to process orders and respond to enquiries. Payments are processed by Razorpay; we never receive or store your full card number, CVV, UPI PIN or net-banking credentials.`,
      `Passwords are stored using one-way bcrypt hashing. We use essential cookies for login, cart and anonymous first-party analytics; we do not sell your data or use third-party advertising trackers.`,
      `You can request access, correction or deletion of your personal data by writing to ${SITE.email}, in line with the Digital Personal Data Protection Act, 2023.`,
    ],
  },
  terms: {
    title: "Terms & Conditions",
    body: [
      `This website is operated by ${SITE.name} (Proprietor: ${SITE.proprietor}, GSTIN ${SITE.gstin}), ${SITE.address.line1}, ${SITE.address.city}, ${SITE.address.state} – ${SITE.address.pincode}.`,
      `All prices are in Indian Rupees and inclusive of GST. We reserve the right to cancel orders arising from pricing errors or stock unavailability, with a full refund.`,
      `EMI, cardless EMI and pay-later options are provided by banks and lending partners through Razorpay; eligibility, interest and charges are decided by the respective lender.`,
      `Any disputes are subject to the jurisdiction of courts in Chengalpattu District, Tamil Nadu.`,
    ],
  },
};

export function generateStaticParams() {
  return Object.keys(POLICIES).map((slug) => ({ slug }));
}

export async function generateMetadata({ params }: PageProps<"/policies/[slug]">): Promise<Metadata> {
  const p = POLICIES[(await params).slug];
  return { title: p?.title ?? "Policy" };
}

async function Policy({ params }: { params: Promise<{ slug: string }> }) {
  const p = POLICIES[(await params).slug];
  if (!p) notFound();
  return (
    <>
      <h1 className="mb-6 font-display text-3xl font-semibold">{p.title}</h1>
      <div className="prose-store space-y-3 text-ink-soft">{p.body.map((t, i) => <p key={i}>{t}</p>)}</div>
    </>
  );
}

export default function PolicyPage({ params }: PageProps<"/policies/[slug]">) {
  return (
    <article className="container-x max-w-3xl py-10">
      <Suspense fallback={<div className="h-64" />}>
        <Policy params={params} />
      </Suspense>
      <p className="mt-8 text-sm text-muted">Questions? Contact {SITE.email} · {SITE.phone}</p>
    </article>
  );
}
